/*
 * A063324  Dimension of the space of weight n cuspidal newforms for Gamma_1(
 *          51 ).
 * https://oeis.org/A063324
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  sign
 * Formula:   a(n) = a(n-1) - a(n-3) + 2·a(n-4) - a(n-5) + a(n-7) - a(n-8) for
 *            n ≥ 12 Initial values (offset 2): a(2)=-1, a(3)=55, a(4)=128,
 *            a(5)=200, a(6)=272, a(7)=342, a(8)=414, a(9)=486, a(10)=556,
 *            a(11)=628. All other terms are generated by the recurrence
 * Range:     i8 n <= 3, i16 n <= 43, i32 n <= 43, i64 n <= 43, i128 n <= 43,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>     /* for uintptr_t if needed */

seq_t a(idx_t n)
{
    if (n < 2u)            /* offset is 2 – values below are irrelevant */
        return 0;

    /* ---- static storage for computed terms -------------------------------- */
    static seq_t *cache      = NULL;   /* array of terms a(0)..a(current_len-1) */
    static size_t cache_len  = 0;       /* number of terms currently stored     */
    static size_t cache_cap  = 0;       /* current allocated size (bytes)        */

    /* ---- initialise cache on first call --------------------------------- */
    if (!cache) {
        /* store values up to index 11 (i.e. 12 elements for 0..11) */
        cache_cap = 12;
        cache_len = 12;
        cache     = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        if (!cache) return 0;   /* allocation failure – shouldn't happen */

        /* initialise all to 0 */
        for (size_t i = 0; i < cache_cap; ++i)
            cache[i] = 0;

        /* known initial values (offset 2) */
        cache[2]  = -1;
        cache[3]  = 55;
        cache[4]  = 128;
        cache[5]  = 200;
        cache[6]  = 272;
        cache[7]  = 342;
        cache[8]  = 414;
        cache[9]  = 486;
        cache[10] = 556;
        cache[11] = 628;
        /* cache[0] and cache[1] remain 0 – they are never used in the
           recurrence for n ≥ 12. */
    }

    /* ---- expand storage if needed --------------------------------------- */
    if (n + 1u > cache_cap) {
        size_t new_cap = n + 1u;
        seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!new_cache) return 0;   /* allocation failure – unlikely       */
        cache = new_cache;
        /* initialise newly added elements to 0 */
        for (size_t i = cache_cap; i < new_cap; ++i)
            cache[i] = 0;
        cache_cap = new_cap;
    }

    /* ---- compute missing terms using the recurrence --------------------- */
    for (idx_t i = cache_len; i <= n; ++i) {
        if (i >= 12) {
            /* a(i) = a(i-1) - a(i-3) + 2·a(i-4) - a(i-5) + a(i-7) - a(i-8) */
            cache[i] = cache[i-1] - cache[i-3] + 2 * cache[i-4]
                                    - cache[i-5] + cache[i-7] - cache[i-8];
        } else {
            /* values for i < 12 are already set in the initialisation */
        }
    }
    cache_len = n + 1u;   /* we have now computed up to n */

    return cache[(size_t)n];
}
